package io.github.jesterportfolio.hearth.economy;

import io.github.jesterportfolio.hearth.persistence.*;
import io.github.jesterportfolio.hearth.inventory.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class EconomyDeskTest {
    private InventoryPayload payload(int n){var slots=new byte[41][];slots[0]=new byte[]{(byte)n};return InventoryPayload.pack(slots);}
    private Properties properties(){try(var r=new java.io.InputStreamReader(Objects.requireNonNull(getClass().getResourceAsStream("/economy-demo.properties")),java.nio.charset.StandardCharsets.UTF_8)){var p=new Properties();p.load(r);return p;}catch(Exception e){throw new AssertionError(e);}}
    @Test void multipleGoodsAndLegacySingleGoods(){var p=properties();var c=EconomyContent.parse(p);var shop=EconomyShop.parse(p,c);assertEquals(List.of("iron_ingot","iron_ore"),shop.goods());assertEquals("철광석",shop.name("iron_ore"));p.remove("merchant-goods");assertEquals(List.of("iron_ingot"),EconomyShop.parse(p,c).goods());}
    @Test void badLinksAndDuplicatesRejected(){for(String value:List.of("missing","iron_ingot,iron_ingot","iron_ore,")){var p=properties();p.setProperty("merchant-goods",value);assertThrows(IllegalArgumentException.class,()->EconomyShop.parse(p,EconomyContent.parse(p)));}}
    @Test void quotesUseSelectedGoodAndHideImpossibleBuy(){var p=properties();var c=EconomyContent.parse(p);var shop=EconomyShop.parse(p,c);var offer=new EconomyStore.Offer(new EconomyContent.Key("capital","iron_ore"),new EconomyEngine.Market(2,100,4),10000);var rows=shop.prices(c,offer);assertEquals(4,rows.size());assertEquals(1,rows.stream().filter(EconomyShop.Price::buy).count());for(var row:rows)assertEquals(EconomyEngine.quote(c,"iron_ore",offer.market(),row.quantity(),row.buy()),row.total());assertThrows(IllegalArgumentException.class,()->shop.prices(c,new EconomyStore.Offer(new EconomyContent.Key("mine","iron_ore"),offer.market(),0)));}
    @Test void catalogPagesAreImmutableAndBounded(){var ids=new ArrayList<String>();var names=new HashMap<String,String>();for(int i=0;i<64;i++){ids.add("g"+i);names.put("g"+i,"품목 "+i);}var shop=new EconomyShop("capital",ids,names);assertEquals(45,shop.page(0).size());assertEquals(19,shop.page(1).size());assertThrows(IllegalArgumentException.class,()->shop.page(2));assertThrows(UnsupportedOperationException.class,()->shop.page(0).clear());}
    private EconomyStore.Request request(){return new EconomyStore.Request(new ServerProgressAccess().forVerifiedServerLink(UUID.randomUUID(),UUID.randomUUID()),UUID.randomUUID(),new EconomyContent.Key("capital","iron_ingot"),1,true,0);}
    @Test void confirmedCommitRequiresExactReceiptRevisionAndPayload(){var r=request();var before=new InventoryStore.Stored(payload(1),4);var after=payload(2);var receipt=new EconomyStore.Entry(r.id(),r.key(),1,true,10,5);assertEquals(EconomyRecovery.Decision.COMMITTED_RELOAD,EconomyRecovery.decide(r,before,after,new EconomyStore.Inspection(Optional.of(receipt),new EconomyStore.Account(90,new InventoryStore.Stored(after,5)))));for(var current:List.of(new InventoryStore.Stored(after,6),new InventoryStore.Stored(payload(3),5)))assertEquals(EconomyRecovery.Decision.REVIEW_REQUIRED,EconomyRecovery.decide(r,before,after,new EconomyStore.Inspection(Optional.of(receipt),new EconomyStore.Account(90,current))));}
    @Test void absentReceiptIsNotAnAutomaticRetry(){var r=request();var before=new InventoryStore.Stored(payload(1),4);assertEquals(EconomyRecovery.Decision.NOT_COMMITTED_RELOAD,EconomyRecovery.decide(r,before,payload(2),new EconomyStore.Inspection(Optional.empty(),new EconomyStore.Account(100,before))));assertEquals(EconomyRecovery.Decision.REVIEW_REQUIRED,EconomyRecovery.decide(r,before,payload(2),new EconomyStore.Inspection(Optional.empty(),new EconomyStore.Account(100,new InventoryStore.Stored(payload(2),5)))));}
    @Test void mismatchedReceiptCannotAuthorizeRecovery(){var r=request();var before=new InventoryStore.Stored(payload(1),4);for(var row:List.of(new EconomyStore.Entry(UUID.randomUUID(),r.key(),1,true,10,5),new EconomyStore.Entry(r.id(),new EconomyContent.Key("mine","iron_ingot"),1,true,10,5),new EconomyStore.Entry(r.id(),r.key(),2,true,10,5),new EconomyStore.Entry(r.id(),r.key(),1,false,10,5)))assertEquals(EconomyRecovery.Decision.REVIEW_REQUIRED,EconomyRecovery.decide(r,before,payload(2),new EconomyStore.Inspection(Optional.of(row),new EconomyStore.Account(90,new InventoryStore.Stored(payload(2),5)))));}
}
